Ext.define('GridHTML.view.GridBuilder', {
    extend: 'Ext.Base',

    requires: [
        'GridHTML.store.AdvancedStore',
        'GridHTML.view.GridAdvanced',
        'GridHTML.view.GridList',
        'GridHTML.store.ListStore',
        'GridHTML.store.OlapStore',
        'GridHTML.view.GridOlap',
        'GridHTML.model.StoreModel',
        'DashletHTML.controller.Translator',
        'DashletHTML.controller.Utils'
    ],

    constructor: function() {
        var me = this;

        me.heightNull = false;
        me.portletID = "";
        me.viewMode = "VIEW";
        me.sessionId = "";
    },

    buildGrid: function(spec, data, opts) {
        var me = this,
            StoreModel = new GridHTML.model.StoreModel(),
            Utils = new DashletHTML.controller.Utils(),
            configSpec = spec,
            gridGeneral = configSpec.laf.viewSpec.gridSpec.gridGeneral,
            localStore,
            senchaBase = null,
            message,
            error = false,
            toReturn,
            _opts = {
                widthViewport: opts.widthViewport,
                customHeaders: opts.customHeaders,
                enableRange: opts.enableRange,
                viewMode: me.viewMode || opts.viewMode,
                sessionId: me.sessionId || opts.sessionId,
                headerOrder: opts.headerOrder,
                linkRender: opts.linkRender,
                hideHeaders: opts.hideHeaders || false,
                portletID: me.portletID || opts.portletID
            };

        switch (gridGeneral.gridType) {

            case "olap":

                genericStore = new GridHTML.store.OlapStore(spec, data, _opts);
                error = me.checkError(genericStore);
                if (!error) {
                    senchaBase = new GridHTML.view.GridOlap();
                    toReturn = senchaBase.buildGrid(spec, genericStore, _opts);
                } else {
                    message = error.message;
                }

                break;

            case "advanced":

                if (_opts.viewMode === "VIEW") {
                    me.advancedStore = genericStore = (me.advancedStore || new GridHTML.store.AdvancedStore());
                } else {
                    genericStore = new GridHTML.store.AdvancedStore();
                }

                localStore = genericStore.buildData(spec, data, _opts);
                error = me.checkError(localStore);
                if (error) {
                    message = error.message;
                } else {
                    me.GridAdvanced = me.GridAdvanced || new GridHTML.view.GridAdvanced(spec, data, _opts);
                    toReturn = me.GridAdvanced.buildGrid(spec, localStore, _opts);
                }

                break;

            case "list":

                genericStore = new GridHTML.store.ListStore();
                localStore = genericStore.buildData(spec, data, _opts);
                error = me.checkError(localStore);
                if (!error) {
                    senchaBase = new GridHTML.view.GridList();
                    toReturn = senchaBase.buildGrid(spec, localStore, _opts);
                } else {
                    message = error.message;
                }
                break;
        }

        //CONTROL DE ERRORES
        if (error) {
            toReturn = Utils.generateSimpleErrorMessage(message);
        }

        toReturn.autoScroll = true;

        return toReturn;






    },

    setConfigs: function(cfg) {
        var me= this;

        me.viewMode = cfg.viewMode || me.viewMode;
        me.sessionId = cfg.sessionId || me.sessionId;
        me.heightNull = cfg.heightNull || me.heightNull;
        me.portletID = cfg.portletID || me.portletID;
        me.viewMode = cfg.viewMode || me.viewMode;
    },

    checkError: function(genericStore) {

        var store = genericStore.store || genericStore;

        if (store.getCount() === 0){
            return {
                type: 0,
                message:  DashletHTML.controller.Translator.getMessage('noData')
            };
        }else if (store.nothingVisible ){
            return {
                type: 1,
                message: DashletHTML.controller.Translator.getMessage('noVisibles')
            }
        }

        return undefined;

    }

});